#version 100

precision highp float;

varying vec2 fragTexCoord;
varying vec4 fragColor;

uniform sampler2D texture0;
uniform sampler2D bloomTexture;
uniform sampler2D lightMap;
uniform float bloomIntensity;

void main()
{
	// Original scene color.
    vec3 scene = texture2D(texture0, fragTexCoord).rgb;

    // Illumination generated by your point lights.
	// rgb(12, 8, 18)
    vec3 light = texture2D(lightMap, fragTexCoord).rgb + vec3(0.6, 0.6, 0.6);


    // Apply illumination and shadows to the scene.
    vec3 litScene = scene * light;

    // Bloom contribution.
    vec3 bloom = texture2D(bloomTexture, fragTexCoord).rgb;

    // Final result.
    vec3 finalColor = litScene + bloom * bloomIntensity;

    gl_FragColor = vec4(finalColor, 1.0);
}
